/**
 * Guidance state machine — pure computation, no React dependencies.
 *
 * Core types and helper functions for confidence-gated turn-by-turn navigation.
 * Drives the live guidance UI overlay and reroute logic.
 */

import type { DirectionStep, NormalizedNodeRecord } from '../domain/navGraph';
import type { PathResult } from '../domain/navGraph';
import type { RouteSessionReadyState } from './routeSessionState';
import type { NormalizedPoint } from '../../src/shared/gps';

// ============================================================
// Core types
// ============================================================

/**
 * GPS and heading confidence classification.
 *
 * Used by `deriveConfidence` to determine how aggressively
 * the guidance engine trusts the current position fix.
 */
export type ConfidenceLevel = 'high' | 'medium' | 'low' | 'none';

/**
 * Phase of the guidance state machine.
 *
 * State transitions are governed by `deriveNextPhase`:
 * - `idle`          → Initial state; no route loaded
 * - `low-confidence` → Route loaded, but GPS/heading signal is weak
 * - `guiding`       → Route active with confident position; advancing steps
 * - `rerouting`     → Off-route detected, computing new path
 * - `arrived`        → User has reached the destination
 */
export type GuidancePhase =
  | 'idle'
  | 'low-confidence'
  | 'guiding'
  | 'rerouting'
  | 'arrived';

/**
 * Core guidance state for live navigation.
 *
 * Carries the route, current position, and confidence signals needed
 * to drive step advancement and reroute decisions.
 */
export interface GuidanceState {
  phase: GuidancePhase;
  /** The route being followed — must be in 'ready' phase. */
  route: RouteSessionReadyState;
  /** Index of the active DirectionStep (0-based). */
  currentStepIndex: number;
  /** User's current position in normalized [0,1] map space. */
  snappedPosition: NormalizedPoint;
  /** Nearest walkable node ID to the snapped position. */
  snappedNodeId: string;
  /** Device compass heading in degrees (0–360), null if unavailable. */
  heading: number | null;
  /** Heading accuracy in degrees, null if unavailable. */
  headingConfidence: number | null;
  /** Classification of current position fix quality. */
  positionConfidence: ConfidenceLevel;
  /** Unix timestamp (ms) of the last position fix. */
  lastFixTimestamp: number;
  /** Unix timestamp (ms) when off-route was first detected, null if on-route. */
  offRouteDetectedAt: number | null;
  /** Consecutive fixes where off-route was detected. */
  offRouteFixCount: number;
  /** Result of the last reroute computation, null if no reroute has been attempted. */
  rerouteResult: PathResult | null;
}

// ============================================================
// Helper function input types
// ============================================================

export interface PositionFix {
  readonly isConfident: boolean;
  readonly accuracyMeters: number | null;
}

export interface HeadingFix {
  readonly headingDegrees: number | null;
  readonly accuracyDegrees: number | null;
}

// ============================================================
// Pure helper functions
// ============================================================

/**
 * Derive the GPS/heading confidence level from position and heading fixes.
 *
 * Confidence levels:
 * - `high`:   GPS fix is confident AND heading accuracy ≤ 15°
 * - `medium`: GPS fix is confident but heading is missing or unreliable (> 15°)
 * - `low`:    GPS fix exists but is not confident
 * - `none`:   No GPS fix or infinite accuracy
 */
export function deriveConfidence(
  positionFix: PositionFix,
  headingFix: HeadingFix,
): ConfidenceLevel {
  // none: no GPS fix or infinite accuracy
  if (
    !positionFix.isConfident
    || positionFix.accuracyMeters == null
    || !Number.isFinite(positionFix.accuracyMeters)
  ) {
    return 'none';
  }

  // low: GPS fix exists but not confident
  if (!positionFix.isConfident) {
    return 'low';
  }

  // medium: GPS confident but heading missing or unreliable
  if (
    headingFix.headingDegrees == null
    || headingFix.accuracyDegrees == null
    || !Number.isFinite(headingFix.accuracyDegrees)
    || headingFix.accuracyDegrees > 15
  ) {
    return 'medium';
  }

  // high: GPS confident AND heading reliable (≤ 15°)
  return 'high';
}

// ============================================================
// Private helpers
// ============================================================

/**
 * Build an ordered coordinate lookup from a path and its route state.
 * Uses the NormalizedNavGraph's nodeById map to resolve node IDs to coordinates.
 */
function buildCoordLookup(
  path: PathResult,
  route: RouteSessionReadyState,
): Map<number, { x: number; y: number }> {
  const nodeById = route.path as unknown as Map<string, NormalizedNodeRecord>;
  const coords = new Map<number, { x: number; y: number }>();
  for (let i = 0; i < path.nodeIds.length; i++) {
    const record = nodeById.get(path.nodeIds[i]);
    if (record) {
      coords.set(i, { x: record.node.x, y: record.node.y });
    }
  }
  return coords;
}

/**
 * Compute perpendicular (orthogonal) distance from a point to a line segment.
 *
 * Returns the minimum distance from `point` to any point on the segment
 * between `segStart` and `segEnd`.
 *
 * Uses the standard point-to-segment formula:
 * Let t = dot(P - segStart, segEnd - segStart) / |segEnd - segStart|²
 * Clamp t to [0, 1] (to stay on the segment)
 * Closest point = segStart + t * (segEnd - segStart)
 * Distance = |P - closest_point|
 */
function pointToSegmentDistance(
  point: NormalizedPoint,
  segStart: { x: number; y: number },
  segEnd: { x: number; y: number },
): number {
  const dx = segEnd.x - segStart.x;
  const dy = segEnd.y - segStart.y;
  const lenSq = dx * dx + dy * dy;

  // Degenerate segment (start === end): return distance to the point
  if (lenSq === 0) {
    return Math.sqrt((point.x - segStart.x) ** 2 + (point.y - segStart.y) ** 2);
  }

  // Parameter t for the projection of P onto the segment line
  const t = Math.max(
    0,
    Math.min(
      1,
      ((point.x - segStart.x) * dx + (point.y - segStart.y) * dy) / lenSq,
    ),
  );

  const closestX = segStart.x + t * dx;
  const closestY = segStart.y + t * dy;

  return Math.sqrt((point.x - closestX) ** 2 + (point.y - closestY) ** 2);
}

// ============================================================
// Public route-geometry helpers
// ============================================================

/**
 * Returns true when the user's position is off the active route segment.
 *
 * Detects deviation by measuring perpendicular distance from the current
 * position to the current path segment (from path.nodeIds[currentStepIndex]
 * to path.nodeIds[currentStepIndex + 1]).
 *
 * @param position     User's current snapped position
 * @param currentStepIndex  Which step in the route is active
 * @param path         The current route path
 * @param route        The route session state (provides normalized graph nodeById)
 * @param threshold    Deviation threshold in normalized units (default: 0.05)
 */
export function isOffRoute(
  position: NormalizedPoint,
  currentStepIndex: number,
  path: PathResult,
  route: RouteSessionReadyState,
  threshold = 0.05,
): boolean {
  if (!path.found || path.nodeIds.length < 2) return false;

  const coords = buildCoordLookup(path, route);

  // When at or beyond the last segment, use distance to the final node
  if (currentStepIndex >= path.nodeIds.length - 1) {
    const lastNode = coords.get(path.nodeIds.length - 1);
    if (!lastNode) return false;

    const dist = Math.sqrt(
      (position.x - lastNode.x) ** 2 + (position.y - lastNode.y) ** 2,
    );
    return dist > threshold;
  }

  const startNode = coords.get(currentStepIndex);
  const endNode = coords.get(currentStepIndex + 1);
  if (!startNode || !endNode) return false;

  const distance = pointToSegmentDistance(position, startNode, endNode);
  return distance > threshold;
}

/**
 * Returns true when the user has reached the waypoint at the start of the next step.
 *
 * Uses the same perpendicular-distance approach as `isOffRoute` but with a
 * smaller threshold so that near-passing doesn't trigger an advance mid-segment.
 *
 * @param position        User's current snapped position
 * @param currentStepIndex  Index of the current step (advance check goes to step + 1)
 * @param path            The current route path
 * @param route           The route session state (provides normalized graph nodeById)
 * @param advanceThreshold  Proximity threshold for triggering advance (default: 0.03)
 */
export function shouldAdvanceStep(
  position: NormalizedPoint,
  currentStepIndex: number,
  path: PathResult,
  route: RouteSessionReadyState,
  advanceThreshold = 0.03,
): boolean {
  if (!path.found || path.nodeIds.length < 2) return false;

  const coords = buildCoordLookup(path, route);

  // If the next step index is beyond the node list, use the last node
  const nextStepIdx = currentStepIndex + 1;
  if (nextStepIdx >= path.nodeIds.length) {
    const lastNode = coords.get(path.nodeIds.length - 1);
    if (!lastNode) return false;
    return (
      Math.sqrt(
        (position.x - lastNode.x) ** 2 + (position.y - lastNode.y) ** 2,
      ) <= advanceThreshold
    );
  }

  const startNode = coords.get(currentStepIndex);
  const endNode = coords.get(nextStepIdx);
  if (!startNode || !endNode) return false;

  const distance = pointToSegmentDistance(position, startNode, endNode);
  return distance <= advanceThreshold;
}

/**
 * Derive the next phase from current state and signals.
 *
 * Phase transition rules:
 * - `idle`          → `isConfident` ? 'guiding' : 'low-confidence'
 * - `low-confidence` → `isConfident` ? 'guiding' : stay 'low-confidence'
 * - `guiding`       → `hasArrived` ? 'arrived'
 *                    → `offRouteFixCount >= rerouteConfirmFixes` ? 'rerouting'
 *                    → stay 'guiding'
 * - `rerouting`     → always transitions to 'guiding' (assumes reroute succeeded)
 * - `arrived`       → stays 'arrived'
 *
 * @param state                  Current guidance state
 * @param isConfident            Whether current position is high or medium confidence
 * @param hasArrived             Whether the user has arrived at the destination
 * @param offRouteFixCount       Number of consecutive off-route position fixes
 * @param rerouteConfirmFixes    Fixes required before triggering reroute (default: 3)
 */
export function deriveNextPhase(
  state: GuidanceState,
  isConfident: boolean,
  hasArrived: boolean,
  offRouteFixCount: number,
  rerouteConfirmFixes = 3,
): GuidancePhase {
  switch (state.phase) {
    case 'idle':
      return isConfident ? 'guiding' : 'low-confidence';

    case 'low-confidence':
      return isConfident ? 'guiding' : 'low-confidence';

    case 'guiding':
      if (hasArrived) return 'arrived';
      if (offRouteFixCount >= rerouteConfirmFixes) return 'rerouting';
      return 'guiding';

    case 'rerouting':
      // Assumes the caller has set rerouteResult; transitions back to guiding
      return 'guiding';

    case 'arrived':
      return 'arrived';
  }
}

/**
 * Return the active DirectionStep for the current step index.
 *
 * Returns null when there is no active route, no directions have been generated,
 * or the current step index is out of bounds.
 */
export function getActiveStep(state: GuidanceState): DirectionStep | null {
  const { route, currentStepIndex } = state;
  if (route.phase !== 'ready') return null;
  if (!route.directions) return null;
  const { steps } = route.directions;
  if (currentStepIndex < 0 || currentStepIndex >= steps.length) return null;
  return steps[currentStepIndex] ?? null;
}

/**
 * Unit tests for guidanceState.ts — pure guidance state machine helpers.
 *
 * Tests:
 * - deriveConfidence: all four confidence levels
 * - isOffRoute: off-route detection, edge cases at path start/end
 * - shouldAdvanceStep: step advancement near waypoints
 * - deriveNextPhase: all phase transitions
 * - getActiveStep: returns correct step from state
 */

import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import type {
  ConfidenceLevel,
  GuidancePhase,
  GuidanceState,
  HeadingFix,
  PositionFix,
} from './guidanceState';
import {
  deriveConfidence,
  isOffRoute,
  shouldAdvanceStep,
  deriveNextPhase,
  getActiveStep,
} from './guidanceState';

// ============================================================
// Mock builders
// ============================================================

/** Minimal mock NavNode for test coordinate data */
function makeNode(id: string, x: number, y: number): import('../../src/shared/types').NavNode {
  return {
    id,
    x,
    y,
    label: id,
    type: 'room',
    searchable: true,
    floorId: 1,
  };
}

/** Build a NormalizedNodeRecord from a NavNode */
function makeNodeRecord(
  node: import('../../src/shared/types').NavNode,
  overrides?: Partial<import('../domain/navGraph').NormalizedNodeRecord>,
): import('../domain/navGraph').NormalizedNodeRecord {
  return {
    buildingId: 1,
    buildingName: 'Test Building',
    floorId: 1,
    floorNumber: 1,
    node,
    ...overrides,
  };
}

/** Minimal PathResult for testing */
function makePath(nodeIds: string[]): import('../domain/navGraph').PathResult {
  return {
    found: true,
    nodeIds,
    totalDistance: 0,
    segments: [],
  };
}

/** Minimal DirectionStep */
function makeStep(instruction: string, icon = 'straight' as const) {
  return {
    instruction,
    icon,
    distanceM: 0,
    durationSec: 0,
    isAccessibleSegment: false,
    floorId: 1,
    floorNumber: 1,
  };
}

/** Minimal RouteSessionReadyState */
function makeRoute(
  path: import('../domain/navGraph').PathResult,
  steps: import('../domain/navGraph').DirectionStep[],
): import('./routeSessionState').RouteSessionReadyState {
  return {
    phase: 'ready',
    start: null,
    destination: null,
    routeMode: 'standard',
    path: path as unknown as import('./routeSessionState').RouteSessionReadyState['path'],
    directions: { steps, totalDistanceNorm: 0, totalDurationSec: 0 },
    errorMessage: null,
  } as import('./routeSessionState').RouteSessionReadyState;
}

/** Build a RouteSessionReadyState path with embedded nodeById map */
function buildRouteWithNodes(
  nodeIds: string[],
  nodeCoords: Array<{ x: number; y: number }>,
  steps: import('../domain/navGraph').DirectionStep[],
): import('./routeSessionState').RouteSessionReadyState {
  const nodes = nodeIds.map((id, i) => makeNode(id, nodeCoords[i]?.x ?? 0, nodeCoords[i]?.y ?? 0));
  const nodeById = new Map<string, import('../domain/navGraph').NormalizedNodeRecord>();
  for (const node of nodes) {
    nodeById.set(node.id, makeNodeRecord(node));
  }

  const path: import('../domain/navGraph').PathResult = {
    found: true,
    nodeIds,
    totalDistance: 0,
    segments: [],
  };

  // Cast path as the internal type (it has a nodeById property for coordinate lookup)
  const routePath = path as unknown as import('./routeSessionState').RouteSessionReadyState['path'] & {
    nodeById: Map<string, import('../domain/navGraph').NormalizedNodeRecord>;
  };
  routePath.nodeById = nodeById;

  return {
    phase: 'ready',
    start: null,
    destination: null,
    routeMode: 'standard',
    path: routePath,
    directions: { steps, totalDistanceNorm: 0, totalDurationSec: 0 },
    errorMessage: null,
  };
}

/** Minimal GuidanceState factory (phase + route only, other fields defaulted) */
function makeGuidanceState(
  phase: GuidancePhase,
  route: import('./routeSessionState').RouteSessionReadyState,
  overrides?: Partial<GuidanceState>,
): GuidanceState {
  return {
    phase,
    route,
    currentStepIndex: 0,
    snappedPosition: { x: 0.5, y: 0.5 },
    snappedNodeId: 'node-0',
    heading: null,
    headingConfidence: null,
    positionConfidence: 'none' as ConfidenceLevel,
    lastFixTimestamp: Date.now(),
    offRouteDetectedAt: null,
    offRouteFixCount: 0,
    rerouteResult: null,
    ...overrides,
  };
}

// ============================================================
// Tests: deriveConfidence
// ============================================================

describe('deriveConfidence', () => {
  it('returns "none" when isConfident is false', () => {
    const pos: PositionFix = { isConfident: false, accuracyMeters: 10 };
    const heading: HeadingFix = { headingDegrees: 45, accuracyDegrees: 5 };
    expect(deriveConfidence(pos, heading)).toBe('none');
  });

  it('returns "none" when accuracyMeters is null', () => {
    const pos: PositionFix = { isConfident: true, accuracyMeters: null };
    const heading: HeadingFix = { headingDegrees: 45, accuracyDegrees: 5 };
    expect(deriveConfidence(pos, heading)).toBe('none');
  });

  it('returns "none" when accuracyMeters is infinite', () => {
    const pos: PositionFix = { isConfident: true, accuracyMeters: Infinity };
    const heading: HeadingFix = { headingDegrees: 45, accuracyDegrees: 5 };
    expect(deriveConfidence(pos, heading)).toBe('none');
  });

  it('returns "none" when accuracyMeters exceeds configured threshold (50m default)', () => {
    const pos: PositionFix = { isConfident: true, accuracyMeters: 75 };
    const heading: HeadingFix = { headingDegrees: 45, accuracyDegrees: 5 };
    // isGpsFixConfident returns false when accuracy > 50m (DEFAULT_MAX_GPS_ACCURACY_METERS)
    expect(deriveConfidence(pos, heading)).toBe('none');
  });

  it('returns "medium" when GPS confident but heading is null', () => {
    const pos: PositionFix = { isConfident: true, accuracyMeters: 20 };
    const heading: HeadingFix = { headingDegrees: null, accuracyDegrees: null };
    expect(deriveConfidence(pos, heading)).toBe('medium');
  });

  it('returns "medium" when GPS confident but headingAccuracy is infinite', () => {
    const pos: PositionFix = { isConfident: true, accuracyMeters: 20 };
    const heading: HeadingFix = { headingDegrees: 90, accuracyDegrees: Infinity };
    expect(deriveConfidence(pos, heading)).toBe('medium');
  });

  it('returns "medium" when GPS confident but headingAccuracy > 15°', () => {
    const pos: PositionFix = { isConfident: true, accuracyMeters: 20 };
    const heading: HeadingFix = { headingDegrees: 90, accuracyDegrees: 25 };
    expect(deriveConfidence(pos, heading)).toBe('medium');
  });

  it('returns "high" when GPS confident AND headingAccuracy ≤ 15°', () => {
    const pos: PositionFix = { isConfident: true, accuracyMeters: 20 };
    const heading: HeadingFix = { headingDegrees: 45, accuracyDegrees: 5 };
    expect(deriveConfidence(pos, heading)).toBe('high');
  });

  it('returns "high" when headingAccuracy exactly 15° (boundary)', () => {
    const pos: PositionFix = { isConfident: true, accuracyMeters: 15 };
    const heading: HeadingFix = { headingDegrees: 90, accuracyDegrees: 15 };
    expect(deriveConfidence(pos, heading)).toBe('high');
  });
});

// ============================================================
// Tests: isOffRoute
// ============================================================

describe('isOffRoute', () => {
  it('returns false when position is on the current segment', () => {
    // Segment from (0.1, 0.1) to (0.9, 0.9), position at midpoint (0.5, 0.5)
    const path = makePath(['a', 'b']);
    const route = buildRouteWithNodes(['a', 'b'], [{ x: 0.1, y: 0.1 }, { x: 0.9, y: 0.9 }], []);
    const position = { x: 0.5, y: 0.5 };
    expect(isOffRoute(position, 0, path, route)).toBe(false);
  });

  it('returns true when position is far from the current segment', () => {
    const path = makePath(['a', 'b']);
    const route = buildRouteWithNodes(['a', 'b'], [{ x: 0.1, y: 0.1 }, { x: 0.9, y: 0.9 }], []);
    // Position (0.9, 0.1) is far above the diagonal segment
    const position = { x: 0.9, y: 0.1 };
    expect(isOffRoute(position, 0, path, route, 0.05)).toBe(true);
  });

  it('returns false near the segment endpoint (within threshold)', () => {
    const path = makePath(['a', 'b']);
    const route = buildRouteWithNodes(['a', 'b'], [{ x: 0.1, y: 0.1 }, { x: 0.9, y: 0.9 }], []);
    // Slightly beyond the end — but close enough to last node
    const position = { x: 0.92, y: 0.88 };
    expect(isOffRoute(position, 0, path, route, 0.05)).toBe(false);
  });

  it('returns false when position is exactly on the path start', () => {
    const path = makePath(['a', 'b']);
    const route = buildRouteWithNodes(['a', 'b'], [{ x: 0.1, y: 0.1 }, { x: 0.9, y: 0.9 }], []);
    const position = { x: 0.1, y: 0.1 };
    expect(isOffRoute(position, 0, path, route, 0.05)).toBe(false);
  });

  it('returns true when position is beyond the last segment and far from last node', () => {
    const path = makePath(['a', 'b']);
    const route = buildRouteWithNodes(['a', 'b'], [{ x: 0.1, y: 0.1 }, { x: 0.9, y: 0.9 }], []);
    // At last segment index — uses distance to last node
    const position = { x: 0.0, y: 0.0 };
    expect(isOffRoute(position, 1, path, route, 0.05)).toBe(true);
  });

  it('returns false when path is not found', () => {
    const path: import('../domain/navGraph').PathResult = { found: false, nodeIds: [], totalDistance: 0, segments: [] };
    const route = buildRouteWithNodes([], [], []);
    const position = { x: 0.5, y: 0.5 };
    expect(isOffRoute(position, 0, path, route)).toBe(false);
  });

  it('returns false for single-node path', () => {
    const path = makePath(['a']);
    const route = buildRouteWithNodes(['a'], [{ x: 0.5, y: 0.5 }], []);
    const position = { x: 0.6, y: 0.6 };
    expect(isOffRoute(position, 0, path, route, 0.05)).toBe(false);
  });

  it('uses custom threshold correctly', () => {
    const path = makePath(['a', 'b']);
    const route = buildRouteWithNodes(['a', 'b'], [{ x: 0.1, y: 0.1 }, { x: 0.9, y: 0.9 }], []);
    // Distance from (0.5, 0.2) to diagonal segment is ~0.18
    const position = { x: 0.5, y: 0.2 };
    expect(isOffRoute(position, 0, path, route, 0.05)).toBe(true);  // > 0.05
    expect(isOffRoute(position, 0, path, route, 0.5)).toBe(false); // < 0.5
  });

  it('returns false for degenerate segment (start === end)', () => {
    const path = makePath(['a', 'a']); // same node
    const route = buildRouteWithNodes(['a', 'a'], [{ x: 0.5, y: 0.5 }, { x: 0.5, y: 0.5 }], []);
    // Distance from position to point should be compared against threshold
    const position = { x: 0.55, y: 0.55 };
    expect(isOffRoute(position, 0, path, route, 0.05)).toBe(false); // ~0.071 < 0.05? actually > 0.05
    // Actually ~0.071 which is > 0.05
    expect(isOffRoute(position, 0, path, route, 0.1)).toBe(false); // ~0.071 < 0.1
  });
});

// ============================================================
// Tests: shouldAdvanceStep
// ============================================================

describe('shouldAdvanceStep', () => {
  it('returns true when position is close to the next waypoint', () => {
    // Segment from (0.1, 0.1) to (0.9, 0.9), position near end (0.88, 0.92)
    const path = makePath(['a', 'b']);
    const route = buildRouteWithNodes(['a', 'b'], [{ x: 0.1, y: 0.1 }, { x: 0.9, y: 0.9 }], []);
    const position = { x: 0.88, y: 0.92 };
    expect(shouldAdvanceStep(position, 0, path, route, 0.03)).toBe(true);
  });

  it('returns false when position is far from the next waypoint', () => {
    const path = makePath(['a', 'b']);
    const route = buildRouteWithNodes(['a', 'b'], [{ x: 0.1, y: 0.1 }, { x: 0.9, y: 0.9 }], []);
    const position = { x: 0.5, y: 0.5 }; // midpoint — perpendicular projection is on segment
    // At midpoint, perp distance to diagonal (0.1,0.1)-(0.9,0.9) is 0
    // So advance = true at midpoint (on segment)
    // Use position clearly off-segment
    const offPos = { x: 0.3, y: 0.7 }; // perpendicular distance ~0.28
    expect(shouldAdvanceStep(offPos, 0, path, route, 0.03)).toBe(false);
  });

  it('advanceThreshold is smaller than offRoute threshold — prevents false reroutes', () => {
    const path = makePath(['a', 'b']);
    const route = buildRouteWithNodes(['a', 'b'], [{ x: 0.1, y: 0.1 }, { x: 0.9, y: 0.9 }], []);
    // A position mid-segment should NOT advance (too early) but also NOT trigger reroute
    const midPos = { x: 0.5, y: 0.5 };
    expect(shouldAdvanceStep(midPos, 0, path, route, 0.03)).toBe(false); // too far from waypoint
    expect(isOffRoute(midPos, 0, path, route, 0.05)).toBe(false); // still on route
  });

  it('returns true at last segment when close to final node', () => {
    const path = makePath(['a', 'b', 'c']);
    const route = buildRouteWithNodes(['a', 'b', 'c'], [
      { x: 0.1, y: 0.1 },
      { x: 0.5, y: 0.5 },
      { x: 0.9, y: 0.9 },
    ], []);
    // At step 2 (last segment), position near final node (0.9, 0.9)
    const position = { x: 0.89, y: 0.91 };
    expect(shouldAdvanceStep(position, 2, path, route, 0.03)).toBe(true);
  });

  it('returns false when path is not found', () => {
    const path: import('../domain/navGraph').PathResult = { found: false, nodeIds: [], totalDistance: 0, segments: [] };
    const route = buildRouteWithNodes([], [], []);
    const position = { x: 0.5, y: 0.5 };
    expect(shouldAdvanceStep(position, 0, path, route)).toBe(false);
  });

  it('returns false when currentStepIndex is at or beyond last node (no next step)', () => {
    const path = makePath(['a', 'b']);
    const route = buildRouteWithNodes(['a', 'b'], [{ x: 0.1, y: 0.1 }, { x: 0.9, y: 0.9 }], []);
    // Step index at last node (1) — next step (2) is beyond path length
    // Falls back to distance to last node
    const nearLast = { x: 0.89, y: 0.91 };
    const farFromLast = { x: 0.1, y: 0.1 };
    expect(shouldAdvanceStep(nearLast, 1, path, route, 0.03)).toBe(true);
    expect(shouldAdvanceStep(farFromLast, 1, path, route, 0.03)).toBe(false);
  });

  it('returns false for single-node path', () => {
    const path = makePath(['a']);
    const route = buildRouteWithNodes(['a'], [{ x: 0.5, y: 0.5 }], []);
    const position = { x: 0.52, y: 0.52 };
    expect(shouldAdvanceStep(position, 0, path, route, 0.03)).toBe(true); // within 0.03 of last node
  });
});

